using System;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
internal static class QuestCaptureUi {
 sealed class Row {internal ComboBox choice;internal bool selected;internal Button toggle;}
 internal static void Show(Window owner,Store store,Action changed,Brush ink,Brush muted,Brush background,Action<Window> probe=null,ResourceDictionary resources=null,IntPtr nativeOwner=default(IntPtr)){
 var w=new Window{Title="Importer mes quêtes terminées",Owner=owner,Width=800,Height=820,MinWidth=620,MinHeight=500,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=background,Foreground=ink,Resources=resources??(owner==null?new ResourceDictionary():owner.Resources)};if(nativeOwner!=IntPtr.Zero)new System.Windows.Interop.WindowInteropHelper(w).Owner=nativeOwner;var body=new StackPanel{Margin=new Thickness(22)};w.Content=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Action<string> label=t=>body.Children.Add(new TextBlock{Text=t,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,6,0,10),Foreground=muted});Func<string,Action,Button> button=(t,a)=>{var b=new Button{Content=t,Margin=new Thickness(0,4,8,4),Padding=new Thickness(12,8,12,8)};b.Click+=delegate{try{a();}catch(Exception e){MessageBox.Show(w,e.Message,"Import de quêtes");}};return b;};
 label("Rattraper ma progression");label("Importez des captures du journal des quêtes TERMINÉES. La lecture reste sur votre PC. Vérifiez les noms avant validation : l’image seule ne garantit pas le statut d’une quête. Seuls les catalogues déjà chargés sont comparés. Aucun trajet, note ou objectif intermédiaire n’est validé automatiquement.");var characters=store.Value.dofus.characters.ToList();var character=new ComboBox{ItemsSource=characters.Select(c=>c.name+" · "+c.server).ToList(),SelectedIndex=Math.Max(0,characters.FindIndex(c=>c.id==store.Value.dofus.active)),Margin=new Thickness(0,5,0,12)};body.Children.Add(character);if(characters.Count==0){label("Créez un personnage avant d’importer vos quêtes.");w.ShowDialog();return;}
 var status=new TextBlock{TextWrapping=TextWrapping.Wrap,Foreground=muted,Margin=new Thickness(0,10,0,10)};var input=new TextBox{Name="CaptureNames",AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Height=150,MaxLength=100000};label("Texte lu dans les captures — corrigez les noms si besoin, une quête par ligne.");body.Children.Add(input);var actions=new WrapPanel();body.Children.Add(actions);body.Children.Add(status);var rowsPanel=new StackPanel();body.Children.Add(rowsPanel);var rows=new List<Row>();CaptureCatalogue catalogue=null;CancellationTokenSource cancel=null;bool reading=false,closed=false,confirmed=false;Button commit=null,confirmation=null;Action clear=()=>{rows.Clear();rowsPanel.Children.Clear();catalogue=null;confirmed=false;if(confirmation!=null)confirmation.Content="○ Je confirme que les quêtes sélectionnées sont terminées";if(commit!=null)commit.IsEnabled=false;};input.TextChanged+=delegate{clear();};character.SelectionChanged+=delegate{clear();};w.Closed+=delegate{closed=true;if(cancel!=null)cancel.Cancel();};
 var choose=button("Ajouter des captures…",()=>{});choose.Click+=async delegate{if(reading)return;var picker=new Microsoft.Win32.OpenFileDialog{Filter="Captures du jeu|*.png;*.jpg;*.jpeg;*.bmp",Multiselect=true};if(picker.ShowDialog(w)!=true)return;if(picker.FileNames.Length>20){status.Text="Ajoutez au maximum 20 captures à la fois.";return;}reading=true;clear();choose.IsEnabled=false;character.IsEnabled=false;cancel=new CancellationTokenSource();var token=cancel.Token;var text=new List<string>();var failures=new List<string>();try{for(int i=0;i<picker.FileNames.Length;i++){token.ThrowIfCancellationRequested();status.Text="Lecture locale de la capture "+(i+1)+" / "+picker.FileNames.Length+"…";var file=picker.FileNames[i];try{text.Add(await Task.Run(()=>QuestCaptureOcr.Read(file,token)));}catch(OperationCanceledException){throw;}catch(Exception e){failures.Add(System.IO.Path.GetFileName(file)+" : "+e.Message);}}if(!closed){input.Text=String.Join(Environment.NewLine,new[]{input.Text}.Concat(text));status.Text="Lecture terminée. Vérifiez le texte puis cliquez sur Analyser les noms."+(failures.Count>0?"\n"+String.Join("\n",failures):"");}}catch(OperationCanceledException){if(!closed)status.Text="Lecture annulée. Les quêtes n’ont pas été modifiées.";}finally{reading=false;if(!closed){choose.IsEnabled=true;character.IsEnabled=true;}cancel.Dispose();cancel=null;}};actions.Children.Add(choose);actions.Children.Add(button("Arrêter la lecture",()=>{if(cancel!=null)cancel.Cancel();}));
 actions.Children.Add(button("Analyser les noms",()=>{if(reading){status.Text="Attendez la fin de la lecture.";return;}clear();var lines=input.Text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(t=>t.Trim()).Where(t=>t.Length>0).Distinct().ToList();if(lines.Count>500)throw new InvalidOperationException("Analysez au maximum 500 lignes à la fois.");catalogue=QuestCaptureImport.Catalogue(store,characters[character.SelectedIndex]);int exactCount=0,unknown=0;foreach(var line in lines){var exact=QuestCaptureImport.Exact(catalogue,line);var candidates=exact.Count>0?exact:QuestCaptureImport.Suggestions(catalogue,line);bool done=exact.Count==1&&QuestCaptureImport.Done(store.Value,characters[character.SelectedIndex].id,exact[0].Id,exact[0].Name);var row=new Row{selected=exact.Count==1&&!done};rows.Add(row);var panel=new StackPanel{Margin=new Thickness(0,7,0,9)};panel.Children.Add(new TextBlock{Text=line+" — "+(done?"déjà importée":exact.Count==1?"nom reconnu":candidates.Count>0?"à vérifier":"non reconnue"),TextWrapping=TextWrapping.Wrap});row.choice=new ComboBox{ItemsSource=candidates,DisplayMemberPath="Label",SelectedIndex=exact.Count==1?0:-1,Margin=new Thickness(0,4,0,4)};panel.Children.Add(row.choice);row.toggle=button(row.selected?"✓ Inclure cette quête":"○ Ignorer cette ligne",()=>{if(row.choice.SelectedItem==null){status.Text="Choisissez d’abord une correspondance. Pour une ligne inconnue, corrigez le texte puis relancez l’analyse.";return;}row.selected=!row.selected;row.toggle.Content=row.selected?"✓ Inclure cette quête":"○ Ignorer cette ligne";});row.choice.SelectionChanged+=delegate{row.selected=false;row.toggle.Content="○ Ignorer cette ligne";};row.toggle.IsEnabled=candidates.Count>0;panel.Children.Add(row.toggle);rowsPanel.Children.Add(panel);if(exact.Count==1)exactCount++;else unknown++;}status.Text=exactCount+" nom(s) reconnu(s), "+unknown+" ligne(s) à vérifier ou ignorées. "+catalogue.Quests.Count+" quêtes dans les guides locaux."+(catalogue.Unreadable>0?" "+catalogue.Unreadable+" guide(s) illisible(s).":"")+(catalogue.Quests.Count==0?" Chargez les guides puis relancez l’analyse.":"");}));
 confirmation=button("○ Je confirme que les quêtes sélectionnées sont terminées",()=>{confirmed=!confirmed;confirmation.Content=confirmed?"✓ Quêtes terminées confirmées":"○ Je confirme que les quêtes sélectionnées sont terminées";commit.IsEnabled=confirmed&&catalogue!=null&&!reading;});body.Children.Add(confirmation);commit=button("Valider l’import pour ce personnage",()=>{if(!confirmed||catalogue==null||reading)return;var selected=rows.Where(r=>r.selected&&r.choice.SelectedItem!=null).Select(r=>(CaptureQuestChoice)r.choice.SelectedItem).GroupBy(q=>q.Id+"/"+QuestCaptureImport.Key(q.Name)).Select(g=>g.First()).ToList();int count=QuestCaptureImport.Commit(store,characters[character.SelectedIndex].id,selected,catalogue);clear();changed();status.Text=count+" quête(s) importée(s). Les autres personnages et les quêtes absentes des captures sont conservés.";});commit.IsEnabled=false;body.Children.Add(commit);
 body.Children.Add(button("Annuler le dernier import de ce personnage",()=>{if(reading)return;var c=characters[character.SelectedIndex];var last=store.Value.dofus.captureHistory.LastOrDefault(b=>b.character==c.id);if(last==null){status.Text="Aucun import à annuler pour ce personnage.";return;}if(MessageBox.Show(w,"Annuler l’import du "+last.date+" ("+last.count+" quêtes) pour "+c.name+" ? Les validations antérieures sont conservées.","Annuler l’import",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;QuestCaptureImport.Undo(store,c.id);clear();changed();status.Text="Dernier import annulé.";}));label("Les 30 derniers imports sont annulables. Les captures ne sont pas conservées par l’application. Les noms importés suivent la sauvegarde du personnage. Les pages Ganymède peuvent regrouper plusieurs quêtes et des trajets : elles ne sont pas cochées en bloc.");body.Children.Add(button("Fermer",w.Close));if(probe!=null)w.Loaded+=delegate{w.Dispatcher.BeginInvoke(new Action(()=>probe(w)));};w.ShowDialog();}
}
